{
  "name": "bt_get_status",
  "confidence": "medium",
  "docstring": "Returns a cached Bluetooth controller status from the global BT block when status-valid flag bits are present in the input HCI/status buffer, otherwise queries a vendor-command result via bt_check_vendor_cmd.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "hci_buffer"
  },
  "struct_hints": [
    {
      "offset": 3,
      "meaning": "flags byte of hci_buffer/status context; bits 0 and 2 indicate a cached controller status is valid"
    },
    {
      "offset": 20,
      "meaning": "cached Bluetooth controller status field at offset 20 of the global BT control block referenced via off_12B760"
    }
  ]
}
